begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into public.employees(id,email,first_name,last_name,display_name,role,rep_code) values
 ('a1000000-0000-4000-8000-000000000001','qr.admin@cmaccontainers.com','QR','Admin','QR Admin','admin','QR-ADMIN'),
 ('a1000000-0000-4000-8000-000000000002','qr.rep@cmaccontainers.com','QR','Rep','QR Rep','sales_rep','QR-REP');
insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
 ('a2000000-0000-4000-8000-000000000001','authenticated','authenticated','qr.admin@cmaccontainers.com','{"provider":"google","providers":["google"]}','{}',now(),now()),
 ('a2000000-0000-4000-8000-000000000002','authenticated','authenticated','qr.rep@cmaccontainers.com','{"provider":"google","providers":["google"]}','{}',now(),now());
select ok(not has_table_privilege('anon','public.qr_submissions','SELECT'),'public cannot read customer answers');
select ok(not has_table_privilege('anon','public.qr_submissions','INSERT'),'public cannot bypass submission validation');
select ok(not has_table_privilege('authenticated','public.qr_submissions','UPDATE'),'employees cannot forge sent state');
select ok(not has_function_privilege('authenticated','public.submit_qr_inquiry(uuid,uuid,jsonb,text,text,text)','EXECUTE'),'authenticated clients cannot call private intake');
select ok(not has_function_privilege('anon','public.record_qr_visit(uuid,text)','EXECUTE'),'public clients cannot bypass visit throttling');
select ok(not has_function_privilege('authenticated','public.claim_qr_notification(uuid)','EXECUTE'),'employees cannot claim emails directly');
select ok(not has_function_privilege('anon','public.qr_admin_report(integer,integer)','EXECUTE'),'anonymous reporting blocked');
select ok(not has_table_privilege('authenticated','private.qr_submission_keys','SELECT'),'idempotency fingerprints stay private');
set local role service_role;
select lives_ok($$select public.record_qr_visit('a3000000-0000-4000-8000-000000000001',repeat('a',64))$$,'server can record visit');
select lives_ok($$select public.record_qr_visit('a3000000-0000-4000-8000-000000000001',repeat('a',64))$$,'refresh is idempotent');
select is((select count(*)::int from public.qr_visits where id='a3000000-0000-4000-8000-000000000001'),1,'visit counted once');
select lives_ok($$select public.submit_qr_inquiry('a4000000-0000-4000-8000-000000000001','a3000000-0000-4000-8000-000000000001','{"name":"QR Visitor","email":"QR@example.com","phone":"6825550100","location":"Burleson, Texas","timing":"Immediately","units":"1-4 units","use":"Short-term rental","payment":"Cash","credit":"Yes"}',repeat('a',64),repeat('a',64),repeat('a',64))$$,'valid inquiry accepted');
select is((select credit from public.qr_submissions where id='a4000000-0000-4000-8000-000000000001'),'','cash never stores a credit answer');
select is(public.submit_qr_inquiry('a4000000-0000-4000-8000-000000000001',null,'{}',repeat('a',64),repeat('a',64),repeat('a',64))->>'created','false','same idempotency key returns existing receipt');
select throws_ok($$select public.submit_qr_inquiry('a4000000-0000-4000-8000-000000000001',null,'{}',repeat('b',64),repeat('a',64),repeat('a',64))$$,'22023',null,'different payload cannot reuse receipt');
select is((select count(*)::int from public.claim_qr_notification('a4000000-0000-4000-8000-000000000001')),1,'only one worker claims notification');
select is((select count(*)::int from public.claim_qr_notification('a4000000-0000-4000-8000-000000000001')),0,'second worker cannot send concurrently');
update public.qr_submissions set email_status='sent',sent_at=now() where id='a4000000-0000-4000-8000-000000000001';
select is((select count(*)::int from public.claim_qr_notification('a4000000-0000-4000-8000-000000000001')),0,'sent mail never resent');
select throws_ok($$select public.submit_qr_inquiry('a4000000-0000-4000-8000-000000000002',null,'{"name":"QR Visitor","email":"qr@example.com","phone":"6825550100","location":"Burleson, Texas","timing":"Immediately","units":"1-4 units","use":"Short-term rental","payment":"Financing","credit":""}',repeat('b',64),repeat('a',64),repeat('a',64))$$,'23514',null,'financing requires valid credit answer');
select throws_ok($$select public.submit_qr_inquiry('a4000000-0000-4000-8000-000000000002',null,'{"name":"QR Visitor","email":"qr@example.com","phone":"6825550100","location":"Nowhere","timing":"Immediately","units":"1-4 units","use":"Short-term rental","payment":"Cash"}',repeat('b',64),repeat('a',64),repeat('a',64))$$,'23514',null,'unknown locations rejected');
select lives_ok($$select public.submit_qr_inquiry('a4000000-0000-4000-8000-000000000002',null,'{"name":"QR Visitor","email":"qr@example.com","phone":"6825550100","location":"Weatherford, Texas","timing":"In 30 days or less","units":"10+ units","use":"Workforce housing","payment":"Financing","credit":"No"}',repeat('b',64),repeat('a',64),repeat('a',64))$$,'form accepted even when analytics was blocked');
update public.qr_submissions set email_status='unknown',last_attempt_at=now()-interval '2 minutes' where id='a4000000-0000-4000-8000-000000000002';
select is((select count(*)::int from public.claim_qr_notification('a4000000-0000-4000-8000-000000000002')),0,'ambiguous emails never auto-retried');
update public.qr_submissions set email_status='failed',attempts=5 where id='a4000000-0000-4000-8000-000000000002';
select is((select count(*)::int from public.claim_qr_notification('a4000000-0000-4000-8000-000000000002')),0,'retry limit enforced');
insert into private.qr_rate_windows values('submit:'||repeat('c',64),date_trunc('hour',now()),10);
select throws_ok($$select public.submit_qr_inquiry('a4000000-0000-4000-8000-000000000003',null,'{}',repeat('c',64),repeat('c',64),repeat('c',64))$$,'P0001','Too many requests. Please try again later.','submission rate limit enforced');
insert into private.qr_rate_windows values('visit:'||repeat('c',64),date_trunc('hour',now()),60);
select throws_ok($$select public.record_qr_visit('a3000000-0000-4000-8000-000000000003',repeat('c',64))$$,'P0001','Too many requests. Please try again later.','visit rate limit enforced');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000002',true);
select is((select count(*)::int from public.qr_submissions),0,'sales reps cannot read QR personal or financing data');
select throws_ok($$select public.qr_admin_report()$$,'42501','Administrator access is required.','sales rep cannot access aggregate reporting');
select set_config('request.jwt.claim.sub','a2000000-0000-4000-8000-000000000001',true);
select is((public.qr_admin_report(0)->>'submissions')::int,2,'admin report counts saved forms including mail failure');
select is((public.qr_admin_report(0)->>'sent')::int,1,'admin report counts only confirmed emails');
select is((public.qr_admin_report(0)->>'converted_visits')::int,1,'conversion excludes untracked inquiries');
select is(jsonb_array_length(public.qr_admin_report(0,25)->'rows'),0,'pagination does not alter aggregate totals');
select throws_ok($$select public.qr_admin_report(-1,0)$$,'22023','Invalid reporting range.','invalid reporting range rejected');
reset role;
update public.employees set active=false where id='a1000000-0000-4000-8000-000000000001';
set local role authenticated;
select is((select count(*)::int from public.qr_submissions),0,'deactivated administrator loses data access immediately');
select throws_ok($$select public.qr_admin_report()$$,'42501','Administrator access is required.','deactivated administrator cannot read report');
reset role;
select * from finish();
rollback;
